function init(){defaults({terms:{},notes:[]})}init();
let bookFilter='全部',query='';const plusDays=n=>daysAgo(-n);
function editBook(id){const b=state.books.find(x=>x.id===id);editModal(b?'修改这本书':'放一本书到书架',field('书名','title','text',b?.title||'','required maxlength="60"')+field('阅读标签','tag','text',b?.tag||'童话','required maxlength="16"'),v=>{if(b)Object.assign(b,v);else state.books.push({...v,id:uid(),borrower:'',date:''});commit('书架已更新')});if(b){$('#edit-form').insertAdjacentHTML('beforeend',btn(b.borrower?'归还后才可以下架':'从书架下架','remove-book','danger',!!b.borrower));on('remove-book',()=>{if(b.borrower)return;state.books=state.books.filter(x=>x.id!==id);closeModal();commit('图书已下架，可撤销')})}}
function borrow(id){const b=state.books.find(x=>x.id===id);editModal('把这本书借回家',`<div class="notice">${esc(b.title)}</div>`+field('借给谁（用代号）','borrower','text',state.borrower||'读者 A','required maxlength="20"')+field('约好哪天归还','due','date',plusDays(14),`required min="${today()}"`),v=>{b.borrower=v.borrower;b.date=today();p.terms[id]={due:v.due,renewals:0};state.borrower=v.borrower;commit('借阅已记录，记得按时归还')},'确认借阅')}
function render(){nav();const available=state.books.filter(x=>!x.borrower),shown=state.books.filter(b=>(bookFilter==='全部'||b.tag===bookFilter)&&(!state.availableOnly||!b.borrower)&&b.title.toLowerCase().includes(query.toLowerCase()));
if(active===0){$('#app').innerHTML=`<div class="two-col"><div>${hero('好故事，轮流读',`${available.length}<small>本现在可以借</small>`,'在自家的小书架，发现下一次冒险。','book')}<label class="search">找一本书<input id="search" type="search" placeholder="搜索书名" value="${esc(query)}"></label><div class="fields" style="margin-bottom:20px">${select('按标签看看','filter',['全部',...new Set(state.books.map(x=>x.tag))],bookFilter)}<label class="checkbox"><input id="available" type="checkbox" ${state.availableOnly?'checked':''}>只看可借</label></div><div class="book-grid">${shown.map(b=>`<article class="book"><div class="book-cover"><small>${esc(b.tag)} / 家庭藏书</small><b>${esc(b.title)}</b><small>借阅馆 · ${b.borrower?'正在旅行':'等你翻开'}</small></div><p>${b.borrower?'借给 '+esc(b.borrower):'在书架 · 可以借阅'}</p><button data-book="${b.id}">${b.borrower?'查看借阅':'借这本书'}</button><button data-edit="${b.id}" class="hint">修改藏书</button></article>`).join('')||empty('没有找到这本书，换个关键词试试。')}</div></div><aside class="stack"><section class="card"><div class="tile-icon">${icon('book')}</div><h3 style="margin:15px 0">让好书多遇见一个人</h3><p class="hint">加上标签、约好归还日期，就能开始一次小小的阅读交换。</p><div style="margin-top:20px">${btn('＋ 添加藏书','add','primary full')}</div></section><p class="subtle">示例书名为虚构。可以换成你们真实拥有的书，成员只用代号。</p></aside></div>`;on('add',()=>editBook());actions('edit',editBook);actions('book',id=>state.books.find(x=>x.id===id).borrower?go(1):borrow(id));$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos)}catch{}};$('[name=filter]').onchange=e=>{bookFilter=e.target.value;render()};$('#available').onchange=e=>{state.availableOnly=e.target.checked;render()}}
if(active===1){$('#app').innerHTML=`<div class="screen-body">${heading('正在旅行的书')}${list(state.books.filter(x=>x.borrower),b=>`<section class="card"><span class="pill">${esc(b.borrower)} 正在读</span><h3 style="margin:14px 0">${esc(b.title)}</h3><p class="hint">借出 ${b.date}${p.terms[b.id]?` · 应还 ${p.terms[b.id].due}`:' · 尚未约定归还日期'}</p>${p.terms[b.id]?.due<today()?'<p class="notice warning">超过约定日期啦，一起确认新的归还时间吧。</p>':''}<div class="row" style="margin-top:16px"><button class="primary" data-return="${b.id}">确认归还</button><button class="secondary" data-renew="${b.id}">延长 7 天</button></div></section>`)}</div>`;actions('return',id=>{const b=state.books.find(x=>x.id===id);confirmAction('这本书已经回到书架了吗？',esc(b.title),()=>{b.borrower='';b.date='';delete p.terms[id];commit('归还成功，又可以借给下一位读者了')})});actions('renew',id=>{const term=p.terms[id]||{due:today(),renewals:0};const start=term.due>today()?term.due:today(),d=new Date(start+'T12:00:00');d.setDate(d.getDate()+7);term.due=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;term.renewals++;p.terms[id]=term;commit('归还日期已延长 7 天')})}
if(active===2){const b=available[0];$('#app').innerHTML=`<div class="screen-body">${heading('给下一位读者的纸条')}${b?`<div class="notice">今天可以看看《${esc(b.title)}》：它属于“${esc(b.tag)}”，而且现在就在书架上。</div>`:''}<section class="card" style="margin-top:20px"><form id="note" class="stack">${select('想聊哪一本','book',state.books.map(x=>x.title))}${textfield('你会怎样推荐它？','text','',400)}<button class="primary" ${state.books.length?'':'disabled'}>留下阅读纸条</button></form></section>${list([...p.notes].reverse(),n=>`<section class="card"><span class="eyebrow">读完 ${esc(n.book||n.title||'一本书')}</span><p>${esc(n.text||n.note||n.reason)}</p><small>${esc(n.date||n.reader||'')}</small></section>`)}</div>`;form('note',v=>{p.notes.push({...v,date:today()});commit('纸条已留下')})}}
shell([['书架','book'],['借阅','people'],['纸条','edit']]);render();
